when SIP_REQUEST {
  log local0. "uri: [SIP::uri] via [SIP::header Via 0]"
}

when SIP_REQUEST {

   # Check if URI contains xyz.com
   if {    [SIP::uri] contains "xyz.com" }{

      # Replace xyz.com with the VIP address
      SIP::uri [string map "xyz.com [IP::local_addr]" [SIP::uri]]
   }
}
